import os
import torch


class Config:
    """
    Global configuration for the Shadow-Aware Wide-Body Network (SA-WBN) pipeline.
    """

    # ==========================================
    # 1. PATHS & DIRECTORIES
    # ==========================================
    # Input Data
    INPUT_DIR = "./input"
    TRAIN_JSON = os.path.join(INPUT_DIR, "train.json")
    TEST_JSON = os.path.join(INPUT_DIR, "test.json")

    # Metadata (Generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory (Specific to Idea 17)
    WORK_DIR = "./working/idea_17"
    CACHE_DIR = os.path.join(WORK_DIR, "cache")
    MODEL_DIR = WORK_DIR

    # Caching
    CACHE_FILE_NAME = "processed_data.npz"
    CACHE_PATH = os.path.join(CACHE_DIR, CACHE_FILE_NAME)

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. DATA PARAMETERS
    # ==========================================
    IMG_HEIGHT = 75
    IMG_WIDTH = 75

    # Input Channels: Band 1 (HH), Band 2 (HV), Average ((HH+HV)/2)
    NUM_CHANNELS = 3

    # Target: 1 (Iceberg) or 0 (Ship)
    NUM_CLASSES = 1

    # Debugging
    DEBUG = False
    DEBUG_SAMPLES = 100  # Number of samples to use if DEBUG is True

    # ==========================================
    # 3. MODEL ARCHITECTURE
    # ==========================================
    # Wide Backbone Filters
    INITIAL_FILTERS = 64
    STAGE_FILTERS = [64, 128, 128, 128]

    # Flattened Vector Size Calculation:
    # Input: 75x75
    # Pool 1: 37x37
    # Pool 2: 18x18
    # Pool 3: 9x9
    # Pool 4: 4x4
    # Final Channels: 128 filters * 2 (Dual Pooling: Max + Min) = 256
    # Flattened: 256 * 4 * 4 = 4096
    LINEAR_INPUT_SIZE = 4096

    # Regularization
    DROPOUT_RATE = 0.5

    # ==========================================
    # 4. TRAINING HYPERPARAMETERS
    # ==========================================
    BATCH_SIZE = 64

    # "Low and Slow" Optimization
    LEARNING_RATE = 2e-4

    NUM_EPOCHS = 100

    # Stratified Cross-Validation
    NUM_FOLDS = 5

    # Early Stopping
    PATIENCE = 15

    # ==========================================
    # 5. SYSTEM & REPRODUCIBILITY
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4
    SEED = 42

    @classmethod
    def setup(cls):
        """
        Creates necessary output directories if they don't exist.
        """
        os.makedirs(cls.WORK_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Configuration setup complete. Working directory: {cls.WORK_DIR}")


# Automatically setup directories when imported
Config.setup()
